-- Fixed plumbing for PostgreSQL Anonymizer. End users do not edit this file;
-- they edit anon/rules.sql. Applied by scripts/anon-run.sh before the rules.

CREATE EXTENSION IF NOT EXISTS anon;
SELECT anon.init();   -- loads the fake data the pseudo_*/fake_* functions need

-- The dumping role: whoever connects as it sees masked data.
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'anon_dumper') THEN
    CREATE ROLE anon_dumper LOGIN;
  END IF;
END $$;

SECURITY LABEL FOR anon ON ROLE anon_dumper IS 'MASKED';
-- Without this setting the MASKED label does nothing and the role reads real data.
ALTER ROLE anon_dumper SET anon.transparent_dynamic_masking TO true;
GRANT pg_read_all_data TO anon_dumper;

-- Start from a clean slate so anon/rules.sql is the single source of truth.
SELECT anon.remove_masks_for_all_columns();
